        'upsert 1 assistant ""',
        'delta 1 "answer 0"',
        'commit 1',
        'stream_end',
        'upsert 2 user "B"',
        'upsert 3 assistant ""',
        'delta 3 "answer 1"',
        'commit 3',
        'stream_end',
      ],
    });
  });

